//
// Runtime localisation, without a resource DLL.
//
// Every user-visible string is written as T(L"简体中文", L"English") at the
// point of use. Those two translations sit on the line that shows them, so a
// missing zh/en pair is a compile-time hole, not a runtime lookup failure.
//
// Five languages ship: Simplified Chinese, English, Traditional Chinese,
// Japanese and Korean. zh and en are passed inline to T(); the other three are
// resolved through a generated lookup table keyed by the Simplified Chinese
// original (see i18n_extra.cpp, generated by tools/gen_i18n.py). A missing row
// falls back to the English inline text, so adding a language never changes a
// single T() call site and an untranslated string degrades to English rather
// than to garbage. tools/check_i18n.py fails the build if any T() key is absent
// from any table, so the fallback is a safety net, not a way to skip work.
//
// Language resolution, highest priority first:
//
//   --lang <tag>            this run only
//   EXPLORERF11_LANG=<tag>  this run only (scripts, portable copies)
//   Language value          the choice made in the tray menu, persisted
//   system locale           GetUserDefaultLocaleName / UI language
//
// The first two override the stored choice because they are explicit,
// per-invocation instructions; the stored choice exists so that a tray click
// survives a restart. English is the fallback for anything unrecognised.
//
// Persistence rule (mirrors the registry policy in config.h): the stored value
// is written only when the chosen language differs from the system language,
// and is deleted when the choice returns to it. A user who never touches the
// language menu leaves no value behind.
#ifndef EF11_I18N_H
#define EF11_I18N_H

#include <windows.h>

namespace ef11 {

// The five shipped languages. Values are stable: they are used as array indices
// and written to the registry as tags via LangTag(), never as these integers.
enum class Lang { Zh, En, ZhHant, Ja, Ko, Count };

inline Lang &LangState() {
    static Lang lang = Lang::Zh;
    return lang;
}

inline void SetLang(Lang lang) { LangState() = lang; }
inline Lang GetLang()            { return LangState(); }
inline bool IsZh()               { return LangState() == Lang::Zh; }

// Accepts the BCP-47 tags a user is likely to type, plus bare/legacy names.
// Traditional Chinese is matched BEFORE the generic zh-* branch so that
// zh-hant / zh-tw / zh-hk cannot be swallowed by Simplified Chinese.
inline bool ParseLang(const wchar_t *s, Lang *out) {
    if (!s) return false;
    if (_wcsicmp(s, L"zh-hant") == 0 || _wcsicmp(s, L"zh-tw") == 0 ||
        _wcsicmp(s, L"zh-hk") == 0 || _wcsicmp(s, L"zh-mo") == 0 ||
        _wcsicmp(s, L"zh-hant-tw") == 0 || _wcsicmp(s, L"zh-hant-hk") == 0) {
        *out = Lang::ZhHant;
        return true;
    }
    if (_wcsicmp(s, L"zh") == 0 || _wcsicmp(s, L"zh-cn") == 0 ||
        _wcsicmp(s, L"zh-hans") == 0 || _wcsicmp(s, L"zh-sg") == 0 ||
        _wcsicmp(s, L"chinese") == 0) {
        *out = Lang::Zh;
        return true;
    }
    if (_wcsicmp(s, L"en") == 0 || _wcsicmp(s, L"en-us") == 0 ||
        _wcsicmp(s, L"en-gb") == 0 || _wcsicmp(s, L"english") == 0) {
        *out = Lang::En;
        return true;
    }
    if (_wcsicmp(s, L"ja") == 0 || _wcsicmp(s, L"ja-jp") == 0 ||
        _wcsicmp(s, L"japanese") == 0) {
        *out = Lang::Ja;
        return true;
    }
    if (_wcsicmp(s, L"ko") == 0 || _wcsicmp(s, L"ko-kr") == 0 ||
        _wcsicmp(s, L"korean") == 0) {
        *out = Lang::Ko;
        return true;
    }
    return false;
}

// The language's own name, in its own script, in the form CLDR uses for the
// zh-Hans / zh-Hant pair. This is the only place a language is named, and the
// value never varies with the current UI language, for two reasons:
//
//   * a selection control must stay usable after a mis-click - the row that
//     switches back has to be recognisable even in a language you cannot read;
//   * a state description must use the same name as the control that produced
//     it, otherwise "UI language: X" and the ticked menu row disagree.
//
// Localised exonyms ("Chinese (Traditional)" in English, 繁体字中国語 in
// Japanese) would need a five-by-five matrix and would break both properties.
inline const wchar_t *LangName(Lang lang) {
    switch (lang) {
    case Lang::Zh:     return L"简体中文";
    case Lang::ZhHant: return L"繁體中文";
    case Lang::En:     return L"English";
    case Lang::Ja:     return L"日本語";
    case Lang::Ko:     return L"한국어";
    default:           return L"English";
    }
}

// Canonical on-disk form, used for the stored Language value.
inline const wchar_t *LangTag(Lang lang) {
    switch (lang) {
    case Lang::Zh:     return L"zh";
    case Lang::ZhHant: return L"zh-Hant";
    case Lang::Ja:     return L"ja";
    case Lang::Ko:     return L"ko";
    case Lang::En:     return L"en";
    default:           return L"en";
    }
}

// EXPLORERF11_LANG, when set to something valid.
inline bool EnvLang(Lang *out) {
    wchar_t env[32] = {0};
    if (!GetEnvironmentVariableW(L"EXPLORERF11_LANG", env, 32)) return false;
    return ParseLang(env, out);
}

// Classify a locale name into one of the five languages. Traditional Chinese
// is checked before the generic zh- prefix, matching ParseLang's precedence.
inline Lang LangFromLocale(const wchar_t *loc) {
    if (!loc || !*loc) return Lang::En;
    if (_wcsnicmp(loc, L"zh", 2) == 0) {
        // zh-hant / zh-tw / zh-hk / zh-mo are Traditional; everything else
        // starting with zh is Simplified.
        if (wcsstr(loc, L"Hant") || wcsstr(loc, L"hant") ||
            _wcsnicmp(loc, L"zh-tw", 5) == 0 || _wcsnicmp(loc, L"zh-hk", 5) == 0 ||
            _wcsnicmp(loc, L"zh-mo", 5) == 0)
            return Lang::ZhHant;
        return Lang::Zh;
    }
    if (_wcsnicmp(loc, L"ja", 2) == 0) return Lang::Ja;
    if (_wcsnicmp(loc, L"ko", 2) == 0) return Lang::Ko;
    return Lang::En;
}

// What this machine speaks, ignoring the stored choice and the environment.
// Several signals, because they disagree often enough to matter: a machine with
// an English UI and a Chinese region should still read as Chinese. The region
// format is authoritative; UI language breaks ties and supplies the script for
// Chinese (SUBLANG_CHINESE_TRADITIONAL vs Simplified).
inline Lang LocaleLang() {
    wchar_t locale[LOCALE_NAME_MAX_LENGTH] = {0};
    if (GetUserDefaultLocaleName(locale, LOCALE_NAME_MAX_LENGTH)) {
        Lang l = LangFromLocale(locale);
        if (l != Lang::En) return l;
    }
    LANGID uis[2] = { GetUserDefaultUILanguage(), GetSystemDefaultUILanguage() };
    for (int i = 0; i < 2; ++i) {
        WORD primary = PRIMARYLANGID(uis[i]), sub = SUBLANGID(uis[i]);
        if (primary == LANG_CHINESE)
            return sub == SUBLANG_CHINESE_TRADITIONAL ? Lang::ZhHant : Lang::Zh;
        if (primary == LANG_JAPANESE) return Lang::Ja;
        if (primary == LANG_KOREAN)   return Lang::Ko;
    }
    return Lang::En;
}

// The default a persisted choice is compared against: environment first (it is
// what the user would see with no stored value), then the machine locale.
inline Lang DefaultLang() {
    Lang l;
    return EnvLang(&l) ? l : LocaleLang();
}

// Defined in i18n_extra.cpp (generated). Looks up the Simplified Chinese key
// in the table for the three non-inline languages; nullptr means "untranslated".
const wchar_t *TranslateExtra(const wchar_t *zh, Lang lang);

// The only localisation primitive. Simplified Chinese and English are inlined
// at the call site; the other three are resolved through the generated table.
// A table miss degrades to the inline English, never to a wrong language.
inline const wchar_t *T(const wchar_t *zh, const wchar_t *en) {
    switch (LangState()) {
    case Lang::Zh: return zh;
    case Lang::En: return en;
    default: {
        const wchar_t *hit = TranslateExtra(zh, LangState());
        return hit ? hit : en;
    }
    }
}

}  // namespace ef11

using ef11::T;

#endif  // EF11_I18N_H
